using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> last(100001, -1);
    int ans = 0, left = 0;

    for (int i = 0; i < N; ++i) {
        int x;
        cin >> x;

        if (last[x] >= left) {
            left = last[x] + 1;
        }

        last[x] = i;
        ans = max(ans, i - left + 1);
    }

    cout << ans << '\n';
    return 0;
